class DigisacWebhookAdapter:
    """Adapt the confirmed Digisac envelope to the application's message shape.

    ``data.id`` maps to ``message_id``, ``data.text`` to ``content``,
    ``data.contactId`` to ``sender_id``, ``data.userId`` to ``user_id``, and
    ``data.ticketId`` to ``conversation_id``.  A ticket is required: buffers
    are deliberately scoped to their final Digisac ticket.
    """

    @classmethod
    def adapt(cls, payload: Mapping[str, Any]) -> AdaptationResult:
        data = payload.get("data")
        if not isinstance(data, Mapping):
            return AdaptationResult(ignored_reason="missing_or_invalid_data")
        data = cast(Mapping[str, Any], data)

        is_from_me = data.get("isFromMe")
        if not isinstance(is_from_me, bool):
            return AdaptationResult(ignored_reason="missing_is_from_me")

        message_type = cls._as_non_empty_string(data.get("type")) or "chat"
        if message_type not in SUPPORTED_MESSAGE_TYPES:
            return AdaptationResult(ignored_reason="unsupported_message_type")

        text = data.get("text")
        content = text.strip() if isinstance(text, str) else ""
        if message_type == "chat" and not content:
            return AdaptationResult(ignored_reason="empty_message_text")

        conversation_id = cls._as_non_empty_string(data.get("ticketId"))
        if conversation_id is None:
            return AdaptationResult(ignored_reason="missing_ticket_id")

        raw_file = data.get("file")
        file_data: Mapping[str, Any] = (
            cast(Mapping[str, Any], raw_file)
            if isinstance(raw_file, Mapping)
            else {}
        )
        # Only safe metadata is normalized; signed URLs never enter the buffer.
        normalized_file = {
            "id": cls._as_non_empty_string(file_data.get("id")),
            "name": cls._as_non_empty_string(file_data.get("name")),
            "public_filename": cls._as_non_empty_string(
                file_data.get("publicFilename")
            ),
            "extension": cls._as_non_empty_string(file_data.get("extension")),
            "mimetype": cls._as_non_empty_string(file_data.get("mimetype")),
        }

        event = payload.get("event")
        return AdaptationResult(
            message=DigisacMessage(
                ticketId=conversation_id,
                id=cls._as_non_empty_string(data.get("id")),
                text=content,
                type=effective_message_type(message_type, normalized_file),
                file=normalized_file,
                contactId=cls._as_non_empty_string(data.get("contactId")),
                isFromMe=is_from_me,
                isFromBot=(
                    data.get("isFromBot")
                    if isinstance(data.get("isFromBot"), bool)
                    else None
                ),
                origin=(
                    data.get("origin")
                    if isinstance(data.get("origin"), str)
                    else None
                ),
                userId=cls._as_non_empty_string(data.get("userId")),
                event=event if isinstance(event, str) else "message.created",
                timestamp=cls._parse_timestamp(data.get("timestamp")),
            )
        )

    @staticmethod
    def _as_non_empty_string(value: Any) -> Optional[str]:
        if value is None:
            return None
        value = str(value).strip()
        return value or None

    @staticmethod
    def _parse_timestamp(value: Any) -> Optional[datetime]:
        if isinstance(value, datetime):
            return value
        if not isinstance(value, str):
            return None
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return None
async def schedule_ticket_closure(
    redis: AsyncRedis, conversation_id: str
) -> tuple[str, str | None]:
    """Atomically replace the pending debounce generation for a ticket."""
    token = uuid.uuid4().hex
    due_at = (
        datetime.now(timezone.utc).timestamp()
        + settings.ticket_closure_debounce_seconds
    )
    previous = await redis.eval(
        SCHEDULE_TICKET_CLOSURE,
        3,
        f"ticket_close_task:{conversation_id}",
        f"ticket_classify_after:{conversation_id}",
        "ia_queue",
        token,
        str(due_at),
        settings.closed_ticket_ttl_seconds,
        conversation_id,
    )
    return token, previous or None


async def append_message_to_buffer(
    redis: AsyncRedis, payload: WebhookPayload | DigisacMessage
) -> tuple[int, bool]:
    """Append a message atomically, so concurrent webhooks do not lose data."""
    now = datetime.now(timezone.utc)
    message_timestamp = payload.get_timestamp() or now
    if message_timestamp.tzinfo is None:
        message_timestamp = message_timestamp.replace(tzinfo=timezone.utc)
    message_timestamp = message_timestamp.astimezone(timezone.utc)
    message = {
        "id": payload.get_message_id(),
        "message_id": payload.get_message_id(),
        "ticket_id": payload.get_conversation_id(),
        "text": payload.get_content(),
        "message_type": payload.get_message_type(),
        "file": payload.get_file(),
        "sender_id": payload.get_sender_id(),
        "isFromMe": getattr(payload, "is_from_me", False),
        "is_from_me": getattr(payload, "is_from_me", False),
        "is_from_bot": getattr(payload, "is_from_bot", None),
        "origin": getattr(payload, "origin", None),
        "userId": getattr(payload, "user_id", None),
        "event_type": payload.get_event(),
        "timestamp": message_timestamp.isoformat(),
        "timestamp_epoch": message_timestamp.timestamp(),
    }
    result = await redis.eval(
        APPEND_MESSAGE_TO_BUFFER,
        3,
        f"buffer:{payload.get_conversation_id()}",
        f"ticket_last_message_at:{payload.get_conversation_id()}",
        f"ticket_close_scheduled:{payload.get_conversation_id()}",
        json.dumps(message),
        now.isoformat(),
        payload.get_conversation_id(),
        settings.ticket_buffer_ttl_seconds,
    )
    return int(result[0]), bool(result[1])


async def enqueue_audio_transcription(
    redis: AsyncRedis, message: DigisacMessage
) -> bool:
    """Persist a durable reservation before publishing the lightweight job."""
    if message.message_type not in AUDIO_MESSAGE_TYPES or not message.message_id:
        return False
    reserved = await reserve_transcription(
        message.message_id,
        message.conversation_id,
        settings.audio_transcription_model,
    )
    if not reserved:
        return False
    try:
        await redis.rpush(
            "audio_transcription_queue",
            json.dumps(
                {
                    "message_id": message.message_id,
                    "conversation_id": message.conversation_id,
                    "attempt": 0,
                }
            ),
        )
    except Exception as exc:
        await release_transcription_publication(
            message.message_id, f"queue publish failed: {exc}"
        )
        raise
    return True


async def enqueue_image_extraction(
    redis: AsyncRedis, message: DigisacMessage
) -> bool:
    """Persist an idempotent reservation before publishing a vision job."""
    if not is_image_message(message.message_type, message.file) or not message.message_id:
        return False
    reserved = await reserve_image_extraction(
        message.message_id,
        message.conversation_id,
        settings.image_vision_model,
