        if data.get("isOpen") is not False:
            logger.info(
                "Ticket event ignored: ticket still open conversation_id=%s", ticket_id
            )
            return {
                "status": "ticket_updated",
                "conversation_id": ticket_id,
                "queued": False,
            }

        protocol = normalize_protocol(data.get("protocol"))
        if protocol is None:
